#ifndef OPUS_BP_ALIGNED_PIPELINE_BASE
#define OPUS_BP_ALIGNED_PIPELINE_BASE
// SPDX-License-Identifier: Apache-2.0

#include "opus_gemm_blockscale_mxscale_bpreshuffle_support_gfx950.cuh"
#include "opus_gemm_blockscale_mxscale_bpreshuffle_traits_register_gfx950.cuh"

#if defined(__HIP_DEVICE_COMPILE__) && defined(__gfx950__)

namespace opus_bpreshuffle_gfx950::aligned::schedule_0 {
using namespace opus_bpreshuffle_gfx950::registers::schedule_0;
// SPDX-License-Identifier: Apache-2.0

template<int MM,int NN,int KK,int BM,int BN,int BK,int WM,int WN,int NB,
int SK,int BD,bool SP,bool NT,bool XCD,bool PIN>
struct pipeline_002_v1_traits {
static constexpr int M=MM,N=NN,K=KK,B_M=BM,B_N=BN,B_K=BK,T_M=WM,T_N=WN;
static constexpr int BLOCK_SIZE=WM*WN*64,MR=BM/(WM*16),NR=BN/(WN*16);
static constexpr int STAGES=NB,GLOBAL_SPLIT=SK,B_AHEAD=BD,B_SETS=BD+1;
static constexpr int KSTEPS=BK/128,PANELS=KK/(BK*SK),TOTAL_SCALES=KK/128;
static constexpr bool PRELOAD=SP,B_DIRECT=BD>0,B_NT=NT,XCD_ORDER=XCD,C_PIN=PIN;
static constexpr bool BYTE_SFB=TOTAL_SCALES%4!=0 || (SP?KK/(128*SK):BK/128)%4!=0;
static constexpr int SCALE_COLS=SP?KK/(128*SK):BK/128;
static constexpr int SB_ROWS=(BN+127)/128,A_BYTES=BM*BK,B_BYTES=BD?0:BN*BK;
static constexpr bool A_TRANSPOSED=MM>1;
static constexpr bool BYTE_SFA=!A_TRANSPOSED && (TOTAL_SCALES%4!=0 || SCALE_COLS%4!=0);
static constexpr int SA_BYTES=((BM*SCALE_COLS*(BYTE_SFA?4:1)+BLOCK_SIZE*4-1)/(BLOCK_SIZE*4))*(BLOCK_SIZE*4);
static constexpr int SB_BYTES=((SB_ROWS*SCALE_COLS*(BYTE_SFB?4:1)+BLOCK_SIZE*4-1)/(BLOCK_SIZE*4))*(BLOCK_SIZE*4);
static constexpr int STAGE_BYTES=((A_BYTES+B_BYTES+(SP?0:SA_BYTES+SB_BYTES)+1023)/1024)*1024;
static constexpr int OFF_SA=SP?NB*STAGE_BYTES:A_BYTES+B_BYTES,OFF_SB=OFF_SA+SA_BYTES;
static constexpr int MAIN_BYTES=NB*STAGE_BYTES+(SP?SA_BYTES+SB_BYTES:0);
static constexpr int C_ROWS=[]() constexpr {
for(int r=BM;r>=16;r-=16)if(BM%r==0 && (r==16 || r*(BN+8)*2<=MAIN_BYTES))return r;
return 16;
}();
static constexpr int FLAG_OFF=MAIN_BYTES>C_ROWS*(BN+8)*2?MAIN_BYTES:C_ROWS*(BN+8)*2;
static constexpr int LDS_BYTES=FLAG_OFF+16;
static constexpr int A_COPIES=A_BYTES/(BLOCK_SIZE*16),B_COPIES=B_BYTES/(BLOCK_SIZE*16);
static constexpr int SA_COPIES=SA_BYTES/(BLOCK_SIZE*4),SB_COPIES=SB_BYTES/(BLOCK_SIZE*4);
static constexpr int MATRIX_ISSUES=A_COPIES+B_COPIES;
static constexpr int SCALE_ISSUES=SA_COPIES+SB_COPIES;
static constexpr int ISSUES=MATRIX_ISSUES+(SP?0:SCALE_ISSUES),B_ISSUES=BD?NR*KSTEPS*2:0;
static constexpr int STEADY=PANELS-(NB-1);
static constexpr int wait_producer(int t) {
int issued=BD*B_ISSUES,end=-1;
if(SP)issued+=SCALE_ISSUES;
for(int i=0;i<NB-1;++i){issued+=ISSUES;if(i==t)end=issued;}
for(int i=0;i<t;++i){
if(BD && i+BD<PANELS)issued+=B_ISSUES;
if(i+NB-1<PANELS){issued+=ISSUES;if(i+NB-1==t)end=issued;}
}
return issued-end;
}
static constexpr int wait_b(int t) {
int issued=0,end=-1;
for(int i=0;i<BD;++i){issued+=B_ISSUES;if(i==t)end=issued;}
if(SP)issued+=SCALE_ISSUES;
issued+=(NB-1)*ISSUES;
for(int i=0;i<=t;++i){
if(i+BD<PANELS){issued+=B_ISSUES;if(i+BD==t)end=issued;}
if(i+NB-1<PANELS)issued+=ISSUES;
}
return issued-end;
}
static constexpr int PHASES=BD>1?B_SETS:1;
static_assert(MM>0 && NN%BN==0 && NN%128==0 && KK%(BK*SK)==0);
static_assert(BM%(WM*16)==0 && BN%(WN*16)==0 && BLOCK_SIZE<=512);
static_assert(A_BYTES%(BLOCK_SIZE*16)==0 && (!BD || BD<NB));
static_assert(BD || B_BYTES%(BLOCK_SIZE*16)==0);
static_assert(PANELS>=NB-1 && LDS_BYTES<=160*1024 && MR*NR*4<=256);
};

#if defined(__HIP_DEVICE_COMPILE__) && defined(__gfx950__)
template<class T> __device__ __forceinline__ 
void pipeline_002_v1_kernel(opus_gemm_blockscale_mxscale_bpreshuffle_kargs_gfx950 args,float* partials,int* counters) {
using namespace opus;
constexpr int M=T::M,N=T::N,K=T::K,BM=T::B_M,BN=T::B_N,BK=T::B_K,SK=T::GLOBAL_SPLIT;
constexpr int NB=T::STAGES,BD=T::B_AHEAD,BS=T::B_SETS,MR=T::MR,NR=T::NR,KS=T::KSTEPS,P=T::PANELS;
constexpr int SC=T::SCALE_COLS,TH=T::BLOCK_SIZE;
const unsigned tid=thread_id_x(),lane=tid%64,lane16=lane%16,kg=lane/16;
const unsigned wave=__builtin_amdgcn_readfirstlane(tid/64),wm=wave/T::T_N,wn=wave%T::T_N;
constexpr unsigned GM=(M+BM-1)/BM,GN=N/BN,TILES=GM*GN;
const unsigned pid=block_id_x();
unsigned tile=pid,split=0;
if constexpr(SK>1){tile=pid/(8*SK)*8+pid%8;split=pid/8%SK;}
else if constexpr(T::XCD_ORDER)tile=pid%8*((TILES+7)/8)+pid/8;
if constexpr(SK>1 || T::XCD_ORDER)if(tile>=TILES)return;
const unsigned row=(tile/GN)*BM,col=(tile%GN)*BN;
const unsigned valid_rows=M-row<BM?M-row:BM,begin=split*P;
auto ga=make_gmem(reinterpret_cast<const fp8_t*>(args.ptr_a),static_cast<unsigned>(M*K));
auto gb=make_gmem(reinterpret_cast<const fp8_t*>(args.ptr_b),static_cast<unsigned>(N*K));
auto gsa=make_gmem(reinterpret_cast<const unsigned char*>(args.ptr_sfa),static_cast<unsigned>(M*T::TOTAL_SCALES));
auto gsb=make_gmem(reinterpret_cast<const unsigned char*>(args.ptr_sfb),static_cast<unsigned>((N/128)*T::TOTAL_SCALES));
auto gc=make_gmem(reinterpret_cast<bf16_t*>(args.ptr_c)+row*N+col,static_cast<unsigned>(valid_rows*N*2));
alignas(16) __shared__ unsigned char arena[T::LDS_BYTES];
auto matrix=make_smem(reinterpret_cast<fp8_t*>(arena));
using Base=mfma<fp8_t,fp8_t,fp32_t,16,16,128>;
array<typename Base::vtype_c,MR*NR> c{};
array<array<array<typename Base::vtype_b,NR>,KS>,T::B_DIRECT?BS:1> bregs;
auto dma=[&](auto& g,auto width,unsigned src,unsigned dst,auto cache){
auto* ptr=reinterpret_cast<OPUS_LDS_ADDR void*>(reinterpret_cast<__UINTPTR_TYPE__>(arena+dst));
__builtin_amdgcn_raw_ptr_buffer_load_async_lds(g.cached_rsrc,ptr,decltype(width)::value,src,0,0,decltype(cache)::value);
};
auto scales=make_smem(reinterpret_cast<unsigned char*>(arena));
array<unsigned,MR> tail_sa;
if constexpr(T::A_TRANSPOSED)static_for<MR>([&](auto mi){
constexpr int m=decltype(mi)::value;
const unsigned ar=row+wm*(BM/T::T_M)+m*16+lane16;
tail_sa[m]=load<1>(gsa,(T::TOTAL_SCALES-1)*M+ar)[0];
});
auto issue_scales=[&](unsigned base,unsigned kt){
static_for<T::SA_COPIES>([&](auto ii){
constexpr int i=decltype(ii)::value;
const unsigned id=i*TH+tid;
if constexpr(T::A_TRANSPOSED){
constexpr int WORDS=BM/4;
const unsigned sc=id/WORDS<SC?id/WORDS:SC-1;
dma(gsa,4_I,(kt*KS+sc)*M+row+(id%WORDS)*4,
base+T::OFF_SA+(i*TH+wave*64)*4,0_I);
} else {
constexpr int WORDS=T::BYTE_SFA?SC:SC/4;
const unsigned sr=id/WORDS<BM?id/WORDS:BM-1;
if constexpr(T::BYTE_SFA){
dma(gsa,1_I,(row+sr)*T::TOTAL_SCALES+kt*KS+id%WORDS,
base+T::OFF_SA+(i*TH+wave*64)*4,0_I);
} else {
const unsigned word=(id%WORDS+WORDS-sr%WORDS)%WORDS;
dma(gsa,4_I,(row+sr)*T::TOTAL_SCALES+kt*KS+word*4,
base+T::OFF_SA+(i*TH+wave*64)*4,0_I);
}
}
});
static_for<T::SB_COPIES>([&](auto ii){
constexpr int i=decltype(ii)::value,WORDS=T::BYTE_SFB?SC:SC/4;
const unsigned id=i*TH+tid,sr=id/WORDS<T::SB_ROWS?id/WORDS:T::SB_ROWS-1;
if constexpr(T::BYTE_SFB){
dma(gsb,1_I,(col/128+sr)*T::TOTAL_SCALES+kt*KS+id%WORDS,
base+T::OFF_SB+(i*TH+wave*64)*4,0_I);
} else {
const unsigned word=(id%WORDS+WORDS-sr%WORDS)%WORDS;
dma(gsb,4_I,(col/128+sr)*T::TOTAL_SCALES+kt*KS+word*4,
base+T::OFF_SB+(i*TH+wave*64)*4,0_I);
}
});
};
auto issue=[&](unsigned slot,unsigned kt){
static_for<T::A_COPIES>([&](auto ii){
constexpr int i=decltype(ii)::value;
const unsigned lin=(i*TH+tid)*16,r=lin/BK,kc=(lin%BK)^((r%(BK/16))*16);
dma(ga,16_I,(row+r)*K+kt*BK+kc,slot*T::STAGE_BYTES+(i*TH+wave*64)*16,0_I);
});
static_for<T::B_COPIES>([&](auto ii){
constexpr int i=decltype(ii)::value;
const unsigned lin=(i*TH+tid)*16,group=lin/(BK*16),within=lin%(BK*16);
dma(gb,16_I,(col/16+group)*(K*16)+kt*(BK*16)+within,slot*T::STAGE_BYTES+T::A_BYTES+(i*TH+wave*64)*16,number<T::B_NT?2:0>{});
});
if constexpr(!T::PRELOAD)issue_scales(slot*T::STAGE_BYTES,kt);
__builtin_amdgcn_asyncmark();
__builtin_amdgcn_sched_barrier(0);
};
auto issue_b=[&](auto bi,unsigned kt){
constexpr int set=decltype(bi)::value;
static_for<KS>([&](auto ki){
constexpr int ks=decltype(ki)::value;
static_for<NR>([&](auto ni){
constexpr int n=decltype(ni)::value;
const unsigned br=col+wn*(BN/T::T_N)+n*16,off=br*K+kt*(BK*16)+ks*2048+kg*256+lane16*16;
set_slice(bregs[set][ks][n],load<16>(gb,off,0,number<T::B_NT?2:0>{}),0_I,16_I);
set_slice(bregs[set][ks][n],load<16>(gb,off+1024,0,number<T::B_NT?2:0>{}),16_I,32_I);
});
});
__builtin_amdgcn_sched_barrier(0);
};
if constexpr(T::B_DIRECT)static_for<BD>([&](auto i){issue_b(i,begin+decltype(i)::value);});
if constexpr(T::PRELOAD)issue_scales(0,begin);
static_for<NB-1>([&](auto i){issue(i,begin+decltype(i)::value);});
auto step=[&](auto ti,unsigned t){
constexpr int t0=decltype(ti)::value,set=t0%BS;
const unsigned slot=t%NB;
constexpr int pending=T::wait_producer(t0),waitb=T::wait_b(t0);
__builtin_amdgcn_wait_asyncmark(t0<T::STEADY?NB-2:P-t0-1);
s_waitcnt(number<(pending>63?63:pending)>{},0_I);
__builtin_amdgcn_s_barrier();
if constexpr(T::B_DIRECT && t0+BD<P)issue_b(number<(set+BD)%BS>{},begin+t+BD);
array<array<typename Base::vtype_a,MR>,KS> af;
array<array<typename Base::vtype_b,NR>,KS> bf;
array<array<unsigned,MR>,KS> as;
array<array<unsigned,NR>,KS> bs;
static_for<KS>([&](auto ki){
constexpr int ks=decltype(ki)::value;
static_for<MR>([&](auto mi){
constexpr int m=decltype(mi)::value;
const unsigned ar=wm*(BM/T::T_M)+m*16+lane16;
const unsigned lo=slot*T::STAGE_BYTES+ar*BK+(((ks*8+kg)^(ar%(BK/16)))*16);
const unsigned hi=slot*T::STAGE_BYTES+ar*BK+(((ks*8+kg+4)^(ar%(BK/16)))*16);
set_slice(af[ks][m],load<16>(matrix,lo),0_I,16_I);
set_slice(af[ks][m],load<16>(matrix,hi),16_I,32_I);
});
if constexpr(!T::B_DIRECT)static_for<NR>([&](auto ni){
constexpr int n=decltype(ni)::value;
const unsigned br=wn*(BN/T::T_N)+n*16,lo=slot*T::STAGE_BYTES+T::A_BYTES+(br/16)*(BK*16)+ks*2048+kg*256+lane16*16;
set_slice(bf[ks][n],load<16>(matrix,lo),0_I,16_I);
set_slice(bf[ks][n],load<16>(matrix,lo+1024),16_I,32_I);
});
const unsigned base=T::PRELOAD?0:slot*T::STAGE_BYTES,sc=T::PRELOAD?t*KS+ks:ks;
static_for<MR>([&](auto mi){
constexpr int m=decltype(mi)::value;
const unsigned ar=wm*(BM/T::T_M)+m*16+lane16;
if constexpr(T::A_TRANSPOSED){
as[ks][m]=load<1>(scales,base+T::OFF_SA+sc*BM+ar)[0];
if constexpr(t0==P-1 && ks==KS-1){
if constexpr(SK==1)as[ks][m]=tail_sa[m];
else if(split==SK-1)as[ks][m]=tail_sa[m];
}
} else {
const unsigned off=T::BYTE_SFA?ar*SC*4+sc*4:
ar*SC+((sc/4+ar)%(SC/4))*4+sc%4;
as[ks][m]=load<1>(scales,base+T::OFF_SA+off)[0];
}
});
static_for<NR>([&](auto ni){
constexpr int n=decltype(ni)::value;
const unsigned sr=(wn*(BN/T::T_N)+n*16)/128;
const unsigned off=T::BYTE_SFB?sr*SC*4+sc*4:sr*SC+((sc/4+sr)%(SC/4))*4+sc%4;
auto* ptr=reinterpret_cast<OPUS_LDS_ADDR unsigned char*>(reinterpret_cast<__UINTPTR_TYPE__>(arena+base+T::OFF_SB+off));
bs[ks][n]=*ptr;
});
});
__builtin_amdgcn_sched_barrier(0);
if constexpr(t0<T::STEADY)issue((slot+NB-1)%NB,begin+t+NB-1);
__builtin_amdgcn_sched_barrier(0);
if constexpr(T::B_DIRECT)s_waitcnt_vmcnt(number<(waitb>63?63:waitb)>{});
s_waitcnt_lgkmcnt(0_I);
static_for<KS>([&](auto ki){
constexpr int ks=decltype(ki)::value;
static_for<MR>([&](auto mi){
constexpr int m=decltype(mi)::value;
static_for<NR>([&](auto ni){
constexpr int n=decltype(ni)::value,ci=m*NR+n;
auto& b=T::B_DIRECT?bregs[set][ks][n]:bf[ks][n];
if constexpr(T::C_PIN){
[[clang::amdgpu_pin_agpr(ci*4)]]
c[ci]=Base{}(af[ks][m],b,c[ci],static_cast<int>(as[ks][m]),static_cast<int>(bs[ks][n]),0_I,0_I);
} else c[ci]=Base{}(af[ks][m],b,c[ci],static_cast<int>(as[ks][m]),static_cast<int>(bs[ks][n]),0_I,0_I);
});
});
});
__builtin_amdgcn_sched_barrier(0);
};
constexpr int START=T::STEADY<NB-1?T::STEADY:NB-1;
static_for<START>([&](auto i){step(i,decltype(i)::value);});
constexpr int GROUPS=(T::STEADY-START)/T::PHASES,END=START+GROUPS*T::PHASES;
if constexpr(GROUPS>0){
#pragma clang loop unroll(disable)
for(unsigned group=0;group<GROUPS;++group){
static_for<T::PHASES>([&](auto i){
constexpr int t0=START+decltype(i)::value;
step(number<t0>{},START+group*T::PHASES+decltype(i)::value);
});
}
}
static_for<P-END>([&](auto i){constexpr int t=END+decltype(i)::value;step(number<t>{},t);});
auto output=[&](auto& vals,auto direct_i){
constexpr bool DIRECT=decltype(direct_i)::value;
auto smc=make_smem(reinterpret_cast<bf16_t*>(arena));
constexpr int CHUNKS=BN/8;
if constexpr(DIRECT){
static_for<MR*NR>([&](auto fi){
constexpr int ci=decltype(fi)::value;
const auto cv=cast<bf16_t>(vals[ci]);
static_for<4>([&](auto ii){
constexpr int e=decltype(ii)::value;
const unsigned rr=wm*(BM/T::T_M)+(ci/NR)*16+kg*4+e;
const unsigned nn=wn*(BN/T::T_N)+(ci%NR)*16+lane16;
if(rr<valid_rows){
auto* dst=reinterpret_cast<bf16_t*>(args.ptr_c)+(int64_t(row)+rr)*N+col+nn;
*dst=cv[e];
}
});
});
} else {
static_for<BM/T::C_ROWS>([&](auto pi){
constexpr int part=decltype(pi)::value;
s_waitcnt_lgkmcnt(0_I);__builtin_amdgcn_s_barrier();
static_for<MR*NR>([&](auto fi){
constexpr int ci=decltype(fi)::value;
const unsigned mr=wm*(BM/T::T_M)+(ci/NR)*16;
const unsigned nn=wn*(BN/T::T_N)+(ci%NR)*16+lane16;
const auto cv=cast<bf16_t>(vals[ci]);
if(mr/T::C_ROWS==part)static_for<4>([&](auto ii){
constexpr int e=decltype(ii)::value;
const unsigned rr=mr%T::C_ROWS+kg*4+e;
store<1>(smc,vector_t<bf16_t,1>{cv[e]},rr*(BN+8)+nn);
});
});
s_waitcnt_lgkmcnt(0_I);__builtin_amdgcn_s_barrier();
static_for<(T::C_ROWS*CHUNKS+TH-1)/TH>([&](auto ii){
constexpr int i=decltype(ii)::value;
const unsigned id=i*TH+tid,rr=id/CHUNKS,ch=id%CHUNKS;
if(rr<T::C_ROWS){
auto cv=load<8>(smc,rr*(BN+8)+ch*8);
store<8>(gc,cv,(part*T::C_ROWS+rr)*N+ch*8);
}
});
});
}
};
if constexpr(SK==1){output(c,0_I);}
else {
constexpr unsigned TILE_ELEMS=BM*BN;
auto gp=make_gmem(partials+int64_t(tile)*SK*TILE_ELEMS,
static_cast<unsigned>(SK*TILE_ELEMS*4));
static_for<MR*NR>([&](auto fi){
constexpr int ci=decltype(fi)::value;
store<4>(gp,c[ci],split*TILE_ELEMS+(ci*TH+tid)*4);
});
s_waitcnt_vmcnt(0_I);__builtin_amdgcn_s_barrier();
auto* flag=reinterpret_cast<OPUS_LDS_ADDR unsigned*>(reinterpret_cast<__UINTPTR_TYPE__>(arena+T::FLAG_OFF));
if(tid==0)*flag=__scoped_atomic_fetch_add(counters+tile,1,__ATOMIC_ACQ_REL,__MEMORY_SCOPE_WRKGRP);
s_waitcnt_lgkmcnt(0_I);__builtin_amdgcn_s_barrier();
const unsigned arrived=*flag;s_waitcnt_lgkmcnt(0_I);
if(arrived==SK-1){
array<typename Base::vtype_c,MR*NR> sums{};
static_for<SK>([&](auto si){
constexpr int sk=decltype(si)::value;
static_for<MR*NR>([&](auto fi){
constexpr int ci=decltype(fi)::value;
sums[ci]+=load<4>(gp,sk*TILE_ELEMS+(ci*TH+tid)*4,0,number<17>{});
});
});
output(sums,number<(BM*BN<=32*32)>{});
if(tid==0)counters[tile]=0;
}
}
}
#endif
}
#endif

#endif

#if defined(OPUS_BP_INCLUDE_ALIGNED_1) && !defined(OPUS_BP_INCLUDE_ALIGNED_1_DONE)
#define OPUS_BP_INCLUDE_ALIGNED_1_DONE
namespace opus_bpreshuffle_gfx950::aligned::schedule_1 {
using namespace opus_bpreshuffle_gfx950::registers::schedule_7;
#ifdef OPUS_FUSED_HOST_TU

// SPDX-License-Identifier: Apache-2.0

template<int MM,int NN,int KK,int BM,int BN,int BK,int WM,int WN,int NB,
int SK,int BD,bool SP,bool NT,bool XCD,bool PIN>
struct pipeline_002_v1_traits {
static constexpr int M=MM,N=NN,K=KK,B_M=BM,B_N=BN,B_K=BK,T_M=WM,T_N=WN;
static constexpr int BLOCK_SIZE=WM*WN*64,MR=BM/(WM*16),NR=BN/(WN*16);
static constexpr int STAGES=NB,GLOBAL_SPLIT=SK,B_AHEAD=BD,B_SETS=BD+1;
static constexpr int KSTEPS=BK/128,PANELS=KK/(BK*SK),TOTAL_SCALES=KK/128;
static constexpr bool PRELOAD=SP,B_DIRECT=BD>0,B_NT=NT,XCD_ORDER=XCD,C_PIN=PIN;
static constexpr bool BYTE_SFB=TOTAL_SCALES%4!=0 || (SP?KK/(128*SK):BK/128)%4!=0;
static constexpr int SCALE_COLS=SP?KK/(128*SK):BK/128;
static constexpr int SB_ROWS=(BN+127)/128,A_BYTES=BM*BK,B_BYTES=BD?0:BN*BK;
static constexpr bool A_TRANSPOSED=MM>1;
static constexpr bool BYTE_SFA=!A_TRANSPOSED && (TOTAL_SCALES%4!=0 || SCALE_COLS%4!=0);
static constexpr int SA_BYTES=((BM*SCALE_COLS*(BYTE_SFA?4:1)+BLOCK_SIZE*4-1)/(BLOCK_SIZE*4))*(BLOCK_SIZE*4);
static constexpr int SB_BYTES=((SB_ROWS*SCALE_COLS*(BYTE_SFB?4:1)+BLOCK_SIZE*4-1)/(BLOCK_SIZE*4))*(BLOCK_SIZE*4);
static constexpr int STAGE_BYTES=((A_BYTES+B_BYTES+(SP?0:SA_BYTES+SB_BYTES)+1023)/1024)*1024;
static constexpr int OFF_SA=SP?NB*STAGE_BYTES:A_BYTES+B_BYTES,OFF_SB=OFF_SA+SA_BYTES;
static constexpr int MAIN_BYTES=NB*STAGE_BYTES+(SP?SA_BYTES+SB_BYTES:0);
static constexpr int C_ROWS=[]() constexpr {
for(int r=BM;r>=16;r-=16)if(BM%r==0 && (r==16 || r*(BN+8)*2<=MAIN_BYTES))return r;
return 16;
}();
static constexpr int FLAG_OFF=MAIN_BYTES>C_ROWS*(BN+8)*2?MAIN_BYTES:C_ROWS*(BN+8)*2;
static constexpr int LDS_BYTES=FLAG_OFF+16;
static constexpr int A_COPIES=A_BYTES/(BLOCK_SIZE*16),B_COPIES=B_BYTES/(BLOCK_SIZE*16);
static constexpr int SA_COPIES=SA_BYTES/(BLOCK_SIZE*4),SB_COPIES=SB_BYTES/(BLOCK_SIZE*4);
static constexpr int MATRIX_ISSUES=A_COPIES+B_COPIES;
static constexpr int SCALE_ISSUES=SA_COPIES+SB_COPIES;
static constexpr int ISSUES=MATRIX_ISSUES+(SP?0:SCALE_ISSUES),B_ISSUES=BD?NR*KSTEPS*2:0;
static constexpr int STEADY=PANELS-(NB-1);
static constexpr int wait_producer(int t) {
int issued=BD*B_ISSUES,end=-1;
if(SP)issued+=SCALE_ISSUES;
for(int i=0;i<NB-1;++i){issued+=ISSUES;if(i==t)end=issued;}
for(int i=0;i<t;++i){
if(BD && i+BD<PANELS)issued+=B_ISSUES;
if(i+NB-1<PANELS){issued+=ISSUES;if(i+NB-1==t)end=issued;}
}
