auto* ptr=reinterpret_cast<OPUS_LDS_ADDR void*>(reinterpret_cast<__UINTPTR_TYPE__>(arena+__builtin_amdgcn_readfirstlane(dst)));
__builtin_amdgcn_raw_ptr_buffer_load_async_lds(g.cached_rsrc,ptr,16,src,__builtin_amdgcn_readfirstlane(scalar),0,decltype(cache)::value);
};
