static_for<T::A_COPIES>([&](auto ii){
constexpr int i=decltype(ii)::value;
matrix_dma(ga,a_offsets[i],kt*BK,slot*T::STAGE_BYTES+(i*TH+wave*64)*16,0_I);
});
static_for<T::B_COPIES>([&](auto ii){
constexpr int i=decltype(ii)::value;
matrix_dma(gb,b_offsets[i],kt*(BK*16),slot*T::STAGE_BYTES+T::A_BYTES+(i*TH+wave*64)*16,number<T::B_NT?2:0>{});
