int* counters=T::GLOBAL_SPLIT>1?reinterpret_cast<int*>(reinterpret_cast<char*>(ws)+4194304ull):nullptr;
constexpr unsigned tiles=((T::M+T::B_M-1)/T::B_M)*(T::N/T::B_N);
constexpr unsigned grid=(T::GLOBAL_SPLIT>1 || T::XCD_ORDER)?((tiles+7)/8*8*T::GLOBAL_SPLIT):tiles;
pipeline_006_v5_kernel<T><<<dim3(grid),dim3(T::BLOCK_SIZE),0,reinterpret_cast<hipStream_t>(stream)>>>(args,partials,counters);
return static_cast<int>(hipGetLastError());
}

template<int Selector, int Variant, int Split>
inline int launch(const void* a, const void* b, void* out, const void* sfa, const void* sfb, void* ws, uint64_t bytes, int m, int n, int k, void* stream) {
    return launch_config(Selector, Split, a, b, sfa, sfb, out, ws, bytes, m, n, k, stream);
}

