void pipeline_010_v15_kernel(const void* ptr_a,const void* ptr_b,const void* ptr_sfa,const void* ptr_sfb,void* ptr_c,float* partials,int* counters) {
using namespace opus;
constexpr int M=T::M,N=T::N,K=T::K,BM=T::B_M,BN=T::B_N,BK=T::B_K,SK=T::GLOBAL_SPLIT;
constexpr int NB=T::STAGES,BD=T::B_AHEAD,BS=T::B_SETS,MR=T::MR,NR=T::NR,KS=T::KSTEPS,P=T::PANELS;
constexpr int SC=T::SCALE_COLS,TH=T::BLOCK_SIZE;
