dma(gsb,1_I,(col/128+sr)*T::TOTAL_SCALES+kt*KS+id%WORDS,
base+T::OFF_SB+(i*TH+wave*64)*4,0_I);
} else {
const unsigned word=(id%WORDS+WORDS-sr%WORDS)%WORDS;
dma(gsb,4_I,(col/128+sr)*T::TOTAL_SCALES+kt*KS+word*4,
base+T::OFF_SB+(i*TH+wave*64)*4,0_I);
}
});
};
auto issue=[&](unsigned slot,unsigned kt){
static_for<T::A_COPIES>([&](auto ii){
constexpr int i=decltype(ii)::value;
const unsigned lin=(i*TH+tid)*16,r=lin/BK,kc=(lin%BK)^((r%(BK/16))*16);
dma(ga,16_I,(row+r)*K+kt*BK+kc,slot*T::STAGE_BYTES+(i*TH+wave*64)*16,0_I);
});
static_for<T::B_COPIES>([&](auto ii){
constexpr int i=decltype(ii)::value;
const unsigned lin=(i*TH+tid)*16,group=lin/(BK*16),within=lin%(BK*16);
dma(gb,16_I,(col/16+group)*(K*16)+kt*(BK*16)+within,slot*T::STAGE_BYTES+T::A_BYTES+(i*TH+wave*64)*16,number<T::B_NT?2:0>{});
});
