if constexpr(T::B_DIRECT)static_for<BD>([&](auto i){issue_b(i,begin+decltype(i)::value);});
if constexpr(T::PRELOAD)issue_scales(0,begin);
static_for<NB-1>([&](auto i){issue(i,begin+decltype(i)::value);});
auto step=[&](auto ti,unsigned t){
constexpr int t0=decltype(ti)::value,set=t0%BS;
