using T=pipeline_010_v15_traits<2,7168,7168,16,32,128,1,2,10,1,0,false,true,false,false>;
int launch_config(
int selector,int launchSplit,const void* a,const void* b,const void* sfa,const void* sfb,
void* out,void* ws,uint64_t bytes,int m,int n,int k,void* stream) {
if(selector!=10 || launchSplit!=T::GLOBAL_SPLIT || m!=T::M || n!=T::N || k!=T::K)return -11;
FixedMContract contract{T::M,T::N,T::K,T::GLOBAL_SPLIT,4,T::BLOCK_SIZE,1,false};
const int checked=fixed_m_validate(contract,0,a,b,out,sfa,sfb,ws,bytes,m,n,k);if(checked)return checked;
if(bytes!=0ull)return -12;
contract.split=1;
auto args=fixed_m_args(contract,a,b,out,sfa,sfb,ws);
float* partials=T::GLOBAL_SPLIT>1?reinterpret_cast<float*>(ws):nullptr;
int* counters=T::GLOBAL_SPLIT>1?reinterpret_cast<int*>(reinterpret_cast<char*>(ws)+458752ull):nullptr;
constexpr unsigned tiles=((T::M+T::B_M-1)/T::B_M)*(T::N/T::B_N);
constexpr unsigned grid=(T::GLOBAL_SPLIT>1 || T::XCD_ORDER)?((tiles+7)/8*8*T::GLOBAL_SPLIT):tiles;
pipeline_010_v15_kernel<T><<<dim3(grid),dim3(T::BLOCK_SIZE),0,reinterpret_cast<hipStream_t>(stream)>>>(a,b,sfa,sfb,out,partials,counters);
return static_cast<int>(hipGetLastError());
}

