array<array<typename Base::vtype_b,NR>,KS> bf;
array<array<unsigned,MR>,KS> as;
array<array<unsigned,NR>,KS> bs;
static_for<KS>([&](auto ki){
constexpr int ks=decltype(ki)::value;
static_for<MR>([&](auto mi){
constexpr int m=decltype(mi)::value;
const unsigned ar=wm*(BM/T::T_M)+m*16+lane16;
const unsigned lo=slot*T::STAGE_BYTES+ar*BK+(((ks*8+kg)^(ar%(BK/16)))*16);
const unsigned hi=slot*T::STAGE_BYTES+ar*BK+(((ks*8+kg+4)^(ar%(BK/16)))*16);
set_slice(af[ks][m],load<16>(matrix,lo),0_I,16_I);
set_slice(af[ks][m],load<16>(matrix,hi),16_I,32_I);
});
if constexpr(!T::B_DIRECT)static_for<NR>([&](auto ni){
constexpr int n=decltype(ni)::value;
const unsigned br=wn*(BN/T::T_N)+n*16,lo=slot*T::STAGE_BYTES+T::A_BYTES+(br/16)*(BK*16)+ks*2048+kg*256+lane16*16;
set_slice(bf[ks][n],load<16>(matrix,lo),0_I,16_I);
set_slice(bf[ks][n],load<16>(matrix,lo+1024),16_I,32_I);
});
