static constexpr bool PRELOAD=SP,B_DIRECT=BD>0,B_NT=NT,XCD_ORDER=XCD,C_PIN=PIN;
static constexpr bool BYTE_SFB=TOTAL_SCALES%4!=0 || (SP?KK/(128*SK):BK/128)%4!=0;
static constexpr int SCALE_COLS=SP?KK/(128*SK):BK/128;
static constexpr int SB_ROWS=(BN+127)/128,A_BYTES=BM*BK,B_BYTES=BD?0:BN*BK;
static constexpr bool A_TRANSPOSED=MM>1;
static constexpr bool BYTE_SFA=!A_TRANSPOSED && (TOTAL_SCALES%4!=0 || SCALE_COLS%4!=0);
static constexpr int SA_BYTES=((BM*SCALE_COLS*(BYTE_SFA?4:1)+BLOCK_SIZE*4-1)/(BLOCK_SIZE*4))*(BLOCK_SIZE*4);
static constexpr int SB_BYTES=((SB_ROWS*SCALE_COLS*(BYTE_SFB?4:1)+BLOCK_SIZE*4-1)/(BLOCK_SIZE*4))*(BLOCK_SIZE*4);
