constexpr int ks=decltype(ki)::value;
static_for<MR>([&](auto mi){
constexpr int m=decltype(mi)::value;
const unsigned ar=wm*(BM/T::T_M)+m*16+lane16;
const unsigned sr=ar%M;
const unsigned lo=T::OFF_WHOLE_A+sr*K+t*BK+(((ks*8+kg)^(sr%(BK/16)))*16);
const unsigned hi=T::OFF_WHOLE_A+sr*K+t*BK+(((ks*8+kg+4)^(sr%(BK/16)))*16);
