struct pipeline_048_v2_traits {
static constexpr int M=MM,N=NN,K=KK,B_M=BM,B_N=BN,B_K=BK,T_M=WM,T_N=WN;
static constexpr int BLOCK_SIZE=WM*WN*64,MR=BM/(WM*16),NR=BN/(WN*16);
