}
static constexpr int wait_b(int t) {
int issued=0,end=-1;
for(int i=0;i<BD;++i){issued+=B_ISSUES;if(i==t)end=issued;}
if(SP)issued+=SCALE_ISSUES;
issued+=(NB-1)*ISSUES;
for(int i=0;i<=t;++i){
if(i+BD<PANELS){issued+=B_ISSUES;if(i+BD==t)end=issued;}
if(i+NB-1<PANELS)issued+=ISSUES;
}
return issued-end;
}
static constexpr int PHASES=BD>1?B_SETS:1;
static_assert(MM>0 && NN%BN==0 && NN%128==0 && KK%(BK*SK)==0);
static_assert(BM%(WM*16)==0 && BN%(WN*16)==0 && BLOCK_SIZE<=512);
static_assert(A_BYTES%(BLOCK_SIZE*16)==0 && (!BD || BD<NB));
static_assert(BD || B_BYTES%(BLOCK_SIZE*16)==0);
