constexpr int n=decltype(ni)::value;
const unsigned br=wn*(BN/T::T_N)+n*16,lo=slot*T::STAGE_BYTES+T::A_BYTES+(br/16)*(BK*16)+ks*2048+kg*256+lane16*16;
