const unsigned wave=__builtin_amdgcn_readfirstlane(tid/64),wm=wave/T::T_N,wn=wave%T::T_N;
constexpr unsigned GM=(M+BM-1)/BM,GN=N/BN,TILES=GM*GN;
const unsigned pid=block_id_x();
unsigned tile=pid,split=0;
if constexpr(SK>1){tile=pid/(8*SK)*8+pid%8;split=pid/8%SK;}
else if constexpr(T::XCD_ORDER)tile=pid%8*((TILES+7)/8)+pid/8;
if constexpr(SK>1 || T::XCD_ORDER)if(tile>=TILES)return;
const unsigned row=(SK>1 || T::XCD_ORDER)?(tile/GN)*BM:(tile%GM)*BM;
const unsigned col=(SK>1 || T::XCD_ORDER)?(tile%GN)*BN:(tile/GM)*BN;
const unsigned valid_rows=M-row<BM?M-row:BM,begin=split*P;
auto ga=make_gmem(reinterpret_cast<const fp8_t*>(args.ptr_a)+row*K,static_cast<unsigned>((M-row)*K));
auto gb=make_gmem(reinterpret_cast<const fp8_t*>(args.ptr_b)+col*K,static_cast<unsigned>((N-col)*K));
constexpr bool SA_COL_MAJOR=T::A_TRANSPOSED;
const unsigned sa_tile=SA_COL_MAJOR?row:row*T::TOTAL_SCALES;
auto gsa=make_gmem(reinterpret_cast<const unsigned char*>(args.ptr_sfa)+sa_tile,static_cast<unsigned>(M*T::TOTAL_SCALES-sa_tile));
const unsigned sb_tile=(col/128)*T::TOTAL_SCALES;
auto gsb=make_gmem(reinterpret_cast<const unsigned char*>(args.ptr_sfb)+sb_tile,static_cast<unsigned>((N/128)*T::TOTAL_SCALES-sb_tile));
auto gc=make_gmem(reinterpret_cast<bf16_t*>(args.ptr_c)+row*N+col,static_cast<unsigned>(valid_rows*N*2));
