using T=pipeline_151_v3_traits<6144,6144,7168,192,256,128,1,4,4,1,3,true,false,false,false>;
int launch_config(
int selector,int launchSplit,const void* a,const void* b,const void* sfa,const void* sfb,
void* out,void* ws,uint64_t bytes,int m,int n,int k,void* stream) {
if(selector!=151 || launchSplit!=T::GLOBAL_SPLIT || m!=T::M || n!=T::N || k!=T::K)return -11;
FixedMContract contract{T::M,T::N,T::K,T::GLOBAL_SPLIT,4,T::BLOCK_SIZE,1,false};
const int checked=fixed_m_validate(contract,0,a,b,out,sfa,sfb,ws,bytes,m,n,k);if(checked)return checked;
if(bytes!=0ull)return -12;
contract.split=1;
