auto* ptr=reinterpret_cast<OPUS_LDS_ADDR void*>(reinterpret_cast<__UINTPTR_TYPE__>(arena+dst));
__builtin_amdgcn_raw_ptr_buffer_load_async_lds(g.cached_rsrc,ptr,decltype(width)::value,src,0,0,decltype(cache)::value);
};
