array<array<typename Base::vtype_b,NR>,KS> bf;
array<array<unsigned,MR>,KS> as;
array<array<unsigned,NR>,KS> bs;
static_for<KS>([&](auto ki){
constexpr int ks=decltype(ki)::value;
const unsigned arow=wm*(BM/T::T_M)+lane16;
const unsigned abase=slot*T::STAGE_BYTES+arow*BK;
const unsigned alo=abase+(((ks*8+kg)^(arow%(BK/16)))*16);
const unsigned ahi=abase+(((ks*8+kg+4)^(arow%(BK/16)))*16);
